-- GreenSolutions 4.0.1 — Ajuda da transação Administração › Textos e idiomas.
-- Grava a ajuda em guniversal_dbp.ajuda_transacoes (editável em Configurações › Ajuda das transações).
-- Só insere quando ainda não existe, para não sobrescrever ajustes feitos pela tela de ajuda.
-- HTML restrito às tags aceitas pelo editor de ajuda (p, h2, ul, ol, li, strong, em, a).
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;

INSERT INTO ajuda_transacoes (transacao, titulo_pt, titulo_en, titulo_es, texto_pt, texto_en, texto_es, ativo)
SELECT 'administracao_idiomas',
       'Ajuda — Textos e idiomas', 'Help — Texts and languages', 'Ayuda — Textos e idiomas',
       '<p>Nesta tela o <strong>ADMINISTRADOR</strong> mantém os textos que aparecem nas telas do GreenSolutions — nomes de colunas, dicas dos botões, títulos e mensagens — em <strong>português (PT)</strong>, <strong>inglês (EN)</strong> e <strong>espanhol (ES)</strong>. Cada usuário vê os textos no idioma escolhido no portal.</p><p>Os textos são <strong>únicos para todas as empresas</strong>. O trabalho é feito em duas etapas: você altera o <strong>rascunho</strong> e depois <strong>publica</strong>. Enquanto não publicar, os usuários continuam vendo os textos anteriores.</p><h2>1. Como a tela está organizada</h2><ul><li><strong>Barra superior:</strong> Salvar rascunho, Publicar, Histórico, Descartar rascunho e Ajuda.</li><li><strong>Linha de situação:</strong> a última publicação (número, data e quem publicou) e etiquetas com o que está pendente.</li><li><strong>Grupos (à esquerda):</strong> <em>Comum</em> reúne os textos que aparecem em todas as telas (Salvar, Novo, Excluir, paginação, mensagens de confirmação…). Os demais grupos são de uma transação, por exemplo <em>Módulo Legal › Controle</em>. O número ao lado é a quantidade de textos; a bolinha indica alterações.</li><li><strong>Lista de textos (à direita):</strong> uma linha por texto. A primeira coluna diz <strong>onde o texto aparece</strong>, o tipo (Título, Coluna, Botão, Dica, Mensagem ou Rótulo) e a chave técnica. As colunas PT, EN e ES são editáveis.</li></ul><h2>2. Cores e marcas</h2><ul><li><strong>Bolinha vermelha / campo com borda vermelha:</strong> alterado e ainda <strong>não salvo</strong>.</li><li><strong>Bolinha laranja / campo amarelado:</strong> salvo no rascunho, <strong>falta publicar</strong>. Abaixo do campo aparece o texto publicado hoje, para comparar.</li><li><strong>Bolinha azul vazada / campo tracejado:</strong> tradução vazia. Nesse caso a tela mostra o texto em português.</li><li><strong>Bolinha cinza:</strong> igual ao publicado.</li></ul><h2>3. Roteiro rápido para alterar um texto</h2><ol><li>Escolha o grupo à esquerda ou digite parte do texto na busca (procura no texto, na chave e no "onde aparece").</li><li>Clique no campo do idioma e digite o novo texto.</li><li>Clique em <strong>Salvar rascunho</strong> (ou <strong>Ctrl+S</strong>).</li><li>Se quiser conferir antes, ligue <strong>Ver rascunho nas telas</strong> e abra a transação: só você verá os textos do rascunho.</li><li>Clique em <strong>Publicar</strong>. A janela mostra cada texto com o valor de antes e o de depois. Escreva o que mudou e confirme.</li><li>Os usuários passam a ver o texto novo ao abrir (ou reabrir) a transação.</li></ol><h2>4. Filtros</h2><ul><li><strong>Não salvos:</strong> só os textos alterados e ainda não salvos.</li><li><strong>Não publicados:</strong> só os textos salvos no rascunho que ainda não foram publicados.</li><li><strong>Tradução faltando:</strong> textos com EN ou ES vazios.</li></ul><p>Os filtros podem ser combinados com o grupo e com a busca.</p><h2>5. Desfazer e descartar</h2><ul><li><strong>Seta circular na linha:</strong> volta aquele texto ao publicado (desfaz o que não foi salvo e descarta o rascunho daquela linha).</li><li><strong>Descartar rascunho:</strong> volta <strong>todos</strong> os textos salvos e não publicados ao texto publicado. Não pode ser desfeito.</li></ul><h2>6. Histórico</h2><p>Mostra cada publicação com número, data, quem publicou e o que mudou. Em <strong>Ver alterações</strong> aparecem os textos daquela publicação, com o valor anterior e o novo. A publicação nº 1 é a carga inicial, feita com os textos que estavam no sistema.</p><h2>7. Regras e cuidados</h2><ul><li>O texto em <strong>português é obrigatório</strong>. EN e ES podem ficar vazios, mas o usuário verá o português.</li><li>Use textos simples, em uma linha. Os caracteres <strong>&lt;</strong> e <strong>&gt;</strong> não são aceitos.</li><li>Uma alteração no grupo <strong>Comum</strong> vale para <strong>todas as telas</strong> que usam aquele texto. Confira com a prévia antes de publicar.</li><li>Nos textos de ajuda da paginação (Página, de, registros), mantenha palavras curtas: elas formam a frase "Página 1 de 9 · 202 registros".</li><li>Se outro administrador salvar os mesmos textos enquanto você edita, sua gravação é recusada para não apagar o trabalho dele. Recarregue a tela e refaça a alteração.</li><li>Por enquanto a transação <em>Módulo Legal › Controle</em> e os textos comuns dos grids estão nesta tela. As demais transações serão incluídas aos poucos.</li></ul><p>Esta ajuda pode ser ajustada em <strong>Configurações › Ajuda das transações</strong>, transação <em>administracao_idiomas</em>.</p>',
       '<p>On this screen the <strong>ADMINISTRADOR</strong> profile maintains the texts shown on GreenSolutions screens — column names, button tooltips, titles and messages — in <strong>Portuguese (PT)</strong>, <strong>English (EN)</strong> and <strong>Spanish (ES)</strong>. Each user sees the texts in the language chosen in the portal.</p><p>The texts are <strong>the same for all companies</strong>. Work happens in two steps: you change the <strong>draft</strong> and then <strong>publish</strong> it. Until you publish, users keep seeing the previous texts.</p><h2>1. How the screen is organized</h2><ul><li><strong>Top bar:</strong> Save draft, Publish, History, Discard draft and Help.</li><li><strong>Status line:</strong> the latest publication (number, date and who published it) and tags showing what is pending.</li><li><strong>Groups (left):</strong> <em>Common</em> holds the texts shown on every screen (Save, New, Delete, pagination, confirmation messages…). The other groups belong to one transaction, for example <em>Legal Module › Control</em>. The number is how many texts it has; the dot shows changes.</li><li><strong>Text list (right):</strong> one row per text. The first column says <strong>where the text appears</strong>, its type (Title, Column, Button, Tooltip, Message or Label) and the technical key. The PT, EN and ES columns can be edited.</li></ul><h2>2. Colors and marks</h2><ul><li><strong>Red dot / red border:</strong> changed and <strong>not saved</strong> yet.</li><li><strong>Orange dot / yellowish field:</strong> saved in the draft, <strong>not published</strong> yet. The currently published text is shown below the field for comparison.</li><li><strong>Hollow blue dot / dashed field:</strong> empty translation. The screen then shows the Portuguese text.</li><li><strong>Grey dot:</strong> same as published.</li></ul><h2>3. Quick steps to change a text</h2><ol><li>Pick the group on the left or type part of the text in the search box (it searches the text, the key and "where it appears").</li><li>Click the field for the language and type the new text.</li><li>Click <strong>Save draft</strong> (or <strong>Ctrl+S</strong>).</li><li>To check it first, turn on <strong>Show draft on screens</strong> and open the transaction: only you will see the draft texts.</li><li>Click <strong>Publish</strong>. The window lists each text with its before and after values. Describe what changed and confirm.</li><li>Users see the new text when they open (or reopen) the transaction.</li></ol><h2>4. Filters</h2><ul><li><strong>Unsaved:</strong> only texts changed and not saved yet.</li><li><strong>Unpublished:</strong> only texts saved in the draft and not published yet.</li><li><strong>Missing translation:</strong> texts with an empty EN or ES.</li></ul><p>Filters can be combined with the group and the search.</p><h2>5. Undo and discard</h2><ul><li><strong>Circular arrow on a row:</strong> reverts that text to the published one (undoes unsaved changes and discards that row''s draft).</li><li><strong>Discard draft:</strong> reverts <strong>all</strong> saved and unpublished texts to the published ones. This cannot be undone.</li></ul><h2>6. History</h2><p>Lists each publication with its number, date, who published it and what changed. <strong>See changes</strong> shows the texts of that publication with the previous and new values. Publication #1 is the initial load, made with the texts that were in the system.</p><h2>7. Rules and tips</h2><ul><li>The <strong>Portuguese text is required</strong>. EN and ES may be empty, but users will then see Portuguese.</li><li>Use plain, single-line texts. The <strong>&lt;</strong> and <strong>&gt;</strong> characters are not accepted.</li><li>A change in the <strong>Common</strong> group applies to <strong>every screen</strong> using that text. Check it with the preview before publishing.</li><li>For the pagination tooltip words (Page, of, records), keep them short: they form the sentence "Page 1 of 9 · 202 records".</li><li>If another administrator saves the same texts while you are editing, your save is refused so their work is not lost. Reload the screen and redo the change.</li><li>For now, the <em>Legal Module › Control</em> transaction and the common grid texts are on this screen. Other transactions will be added gradually.</li></ul><p>This help can be adjusted in <strong>Settings › Transaction help</strong>, transaction <em>administracao_idiomas</em>.</p>',
       '<p>En esta pantalla el perfil <strong>ADMINISTRADOR</strong> mantiene los textos que aparecen en las pantallas de GreenSolutions — nombres de columnas, ayudas de los botones, títulos y mensajes — en <strong>portugués (PT)</strong>, <strong>inglés (EN)</strong> y <strong>español (ES)</strong>. Cada usuario ve los textos en el idioma elegido en el portal.</p><p>Los textos son <strong>únicos para todas las empresas</strong>. El trabajo se hace en dos etapas: usted modifica el <strong>borrador</strong> y después lo <strong>publica</strong>. Mientras no publique, los usuarios siguen viendo los textos anteriores.</p><h2>1. Cómo está organizada la pantalla</h2><ul><li><strong>Barra superior:</strong> Guardar borrador, Publicar, Historial, Descartar borrador y Ayuda.</li><li><strong>Línea de situación:</strong> la última publicación (número, fecha y quién publicó) y etiquetas con lo pendiente.</li><li><strong>Grupos (a la izquierda):</strong> <em>Común</em> reúne los textos que aparecen en todas las pantallas (Guardar, Nuevo, Eliminar, paginación, mensajes de confirmación…). Los demás grupos son de una transacción, por ejemplo <em>Módulo Legal › Control</em>. El número es la cantidad de textos; el punto indica cambios.</li><li><strong>Lista de textos (a la derecha):</strong> una fila por texto. La primera columna indica <strong>dónde aparece el texto</strong>, el tipo (Título, Columna, Botón, Ayuda, Mensaje o Rótulo) y la clave técnica. Las columnas PT, EN y ES son editables.</li></ul><h2>2. Colores y marcas</h2><ul><li><strong>Punto rojo / borde rojo:</strong> modificado y aún <strong>no guardado</strong>.</li><li><strong>Punto naranja / campo amarillento:</strong> guardado en el borrador, <strong>falta publicar</strong>. Debajo del campo aparece el texto publicado hoy, para comparar.</li><li><strong>Punto azul hueco / campo punteado:</strong> traducción vacía. En ese caso la pantalla muestra el texto en portugués.</li><li><strong>Punto gris:</strong> igual al publicado.</li></ul><h2>3. Pasos rápidos para cambiar un texto</h2><ol><li>Elija el grupo a la izquierda o escriba parte del texto en la búsqueda (busca en el texto, la clave y "dónde aparece").</li><li>Haga clic en el campo del idioma y escriba el nuevo texto.</li><li>Haga clic en <strong>Guardar borrador</strong> (o <strong>Ctrl+S</strong>).</li><li>Para revisarlo antes, active <strong>Ver borrador en las pantallas</strong> y abra la transacción: solo usted verá los textos del borrador.</li><li>Haga clic en <strong>Publicar</strong>. La ventana muestra cada texto con el valor anterior y el nuevo. Escriba qué cambió y confirme.</li><li>Los usuarios ven el texto nuevo al abrir (o volver a abrir) la transacción.</li></ol><h2>4. Filtros</h2><ul><li><strong>Sin guardar:</strong> solo los textos modificados y aún no guardados.</li><li><strong>No publicados:</strong> solo los textos guardados en el borrador que aún no se publicaron.</li><li><strong>Traducción faltante:</strong> textos con EN o ES vacíos.</li></ul><p>Los filtros se pueden combinar con el grupo y la búsqueda.</p><h2>5. Deshacer y descartar</h2><ul><li><strong>Flecha circular en la fila:</strong> vuelve ese texto al publicado (deshace lo no guardado y descarta el borrador de esa fila).</li><li><strong>Descartar borrador:</strong> vuelve <strong>todos</strong> los textos guardados y no publicados al texto publicado. No se puede deshacer.</li></ul><h2>6. Historial</h2><p>Muestra cada publicación con número, fecha, quién publicó y qué cambió. En <strong>Ver cambios</strong> aparecen los textos de esa publicación con el valor anterior y el nuevo. La publicación n.º 1 es la carga inicial, hecha con los textos que estaban en el sistema.</p><h2>7. Reglas y cuidados</h2><ul><li>El texto en <strong>portugués es obligatorio</strong>. EN y ES pueden quedar vacíos, pero el usuario verá el portugués.</li><li>Use textos simples, en una línea. Los caracteres <strong>&lt;</strong> y <strong>&gt;</strong> no se aceptan.</li><li>Un cambio en el grupo <strong>Común</strong> vale para <strong>todas las pantallas</strong> que usan ese texto. Revíselo con la vista previa antes de publicar.</li><li>En las palabras de la ayuda de la paginación (Página, de, registros), use palabras cortas: forman la frase "Página 1 de 9 · 202 registros".</li><li>Si otro administrador guarda los mismos textos mientras usted edita, su grabación se rechaza para no borrar el trabajo del otro. Recargue la pantalla y rehaga el cambio.</li><li>Por ahora la transacción <em>Módulo Legal › Control</em> y los textos comunes de las cuadrículas están en esta pantalla. Las demás transacciones se incluirán poco a poco.</li></ul><p>Esta ayuda puede ajustarse en <strong>Configuraciones › Ayuda de las transacciones</strong>, transacción <em>administracao_idiomas</em>.</p>',
       1
 WHERE NOT EXISTS (SELECT 1 FROM ajuda_transacoes WHERE transacao = 'administracao_idiomas');

INSERT INTO green_universal_migrations (codigo_migracao, versao, status, detalhes)
VALUES ('GREEN_IDIOMAS_AJUDA_211', '4.0.1', 'CONCLUIDA', JSON_OBJECT('transacao', 'administracao_idiomas', 'tabela', 'ajuda_transacoes'))
ON DUPLICATE KEY UPDATE status = VALUES(status), detalhes = VALUES(detalhes), executado_em = CURRENT_TIMESTAMP;
